; ---------------------------------------------------------------
; void __near__ game_deckswabber (void)
; ---------------------------------------------------------------

.segment	"BANK1"

.proc	_game_deckswabber: near

.segment	"BANK1"

;
; pad1 = pad_poll(0); // read the first controller
;
	lda     #$00
	jsr     _pad_poll
	sta     _pad1
;
; pad1_new = get_pad_new(0);
;
	lda     #$00
	jsr     _get_pad_new
	sta     _pad1_new
;
; ppu_wait_nmi(); // wait till beginning of the frame
;
	jsr     _ppu_wait_nmi
;
; clear_vram_buffer();
;
	jsr     _clear_vram_buffer
;
; set_prg_bank(DECKSWABBER_CODE_BANK);
;
	lda     #$01
	jsr     _set_prg_bank
;
; deckswabber_player_movement();
;
	jsr     _deckswabber_player_movement
;
; deckswabber_draw_sprites();
;
	jsr     _deckswabber_draw_sprites
;
; if (pad1 & PAD_B) {
;
	lda     _pad1
	and     #$40
	cmp     #$00
;
; end_deckswabber();
;
	jne     _end_deckswabber
;
; }
;
	rts

.endproc

; ---------------------------------------------------------------
; void __near__ begin_deckswabber (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_begin_deckswabber: near

.segment	"CODE"

;
; pal_fade_to(4, 0);
;
	lda     #$04
	jsr     pusha
	lda     #$00
	jsr     _pal_fade_to
;
; prepare_screen_transition();
;
	jsr     _prepare_screen_transition
;
; set_prg_bank(5);
;
	lda     #$05
	jsr     _set_prg_bank
;
; temppointer = deckswabber_game_screen;
;
	lda     #<(_deckswabber_game_screen)
	ldx     #>(_deckswabber_game_screen)
	sta     _temppointer
	stx     _temppointer+1
;
; LZG_decode(temppointer, cmap);
;
	jsr     pushax
	lda     #<(_cmap)
	ldx     #>(_cmap)
	jsr     _LZG_decode
;
; vram_write(cmap, 32*32);
;
	lda     #<(_cmap)
	ldx     #>(_cmap)
	jsr     pushax
	ldx     #$04
	lda     #$00
	jsr     _vram_write
;
; memfill(cmap, 0, 64 + 64 + 32); // 64 game board tiles + 64 game board enemy presences + 32 characters for text buffering
;
	jsr     decsp3
	lda     #<(_cmap)
	ldy     #$01
	sta     (sp),y
	iny
	lda     #>(_cmap)
	sta     (sp),y
	lda     #$00
	tay
	sta     (sp),y
	tax
	lda     #$A0
	jsr     _memfill
;
; set_prg_bank(DECKSWABBER_CODE_BANK);
;
	lda     #$01
	jsr     _set_prg_bank
;
; begin_deckswabber_sub();
;
	jmp     _begin_deckswabber_sub

.endproc

; ---------------------------------------------------------------
; void __near__ begin_deckswabber_sub (void)
; ---------------------------------------------------------------

.segment	"BANK1"

.proc	_begin_deckswabber_sub: near

.segment	"BANK1"

;
; music_play(ICE_CREAM_MACHINE_SONG);
;
	lda     #$07
	jsr     _music_play
;
; game_mode = MODE_GAME;
;
	lda     #$01
	sta     _game_mode
;
; seed_rng();
;
	jsr     _seed_rng
;
; srand(rand8());
;
	jsr     _rand8
	ldx     #$00
	jsr     _srand
;
